/// The big slot's two door tools, the hammer and the breaching shotgun: they open any shut door that is not steel, from either face and from beside the latch
/// jamb. `swings` blows of the hammer take a lock where the frame holds a boot (one blow where a boot would do), one every `swing` seconds, the first after `heft`;
/// `shells` yours may put into one lock before you give it up. You take the row from `reach` metres of the door and walk to a free place beside either jamb. The
/// tool changes hands with the weight of a gun swap: `equip_w`, `draw_w` and `stow_w` seconds, and the hammer's wind-up begun `flow` s before it is fully out.
#[derive(Clone, Copy, Debug, ToBytes, Knobs)]
pub struct BigslotK {
    #[k(2.0)] pub swings: f64,
    #[k(0.7)] pub swing: f64,
    #[k(2.0)] pub shells: f64,
    #[k(2.4)] pub reach: f64,
    #[k(0.7)] pub heft: f64,
    #[k(0.8)] pub equip_w: f64,
    #[k(0.7)] pub draw_w: f64,
    #[k(0.75)] pub stow_w: f64,
    #[k(0.2)] pub flow: f64,
}
